package com.gymmind.ai.api; import com.gymmind.ai.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/ai") public class AiChatController {private final AiChatService service;private final CurrentActorProvider actors;public AiChatController(AiChatService s,CurrentActorProvider a){service=s;actors=a;} @PostMapping("/chat") public ApiResponse<AiChatView> chat(@RequestBody ChatRequest r){return ApiResponse.success(service.chat(actors.requireCurrent(),r.sessionId(),r.question()));} public record ChatRequest(String sessionId,String question){} }
